// src/servicios/api.js
import axios from "axios";

/**
 * Base URL:
 * - Compatible con CRA (process.env.REACT_APP_*) y Vite (import.meta.env.VITE_*).
 * - Ajusta el valor por defecto para que sea consistente con tu Django en dev.
 *   Recomendado: usar 127.0.0.1 en FE y BE para SameSite=Lax (same-site).
 */
const API_BASE_URL =
  (typeof import.meta !== "undefined" &&
    import.meta.env &&
    import.meta.env.VITE_API_BASE_URL) ||
  process.env.REACT_APP_API_BASE_URL ||
  // ⬇️ Cambia este default a 127.0.0.1 si tu Django está así (recomendado):
  "http://127.0.0.1:8000/api";
// "http://localhost:8000/api"; // alternativa si usas localhost en ambos (FE/BE)

const api = axios.create({
  baseURL: API_BASE_URL,
  withCredentials: true, // necesario para enviar/recibir cookies (sessionid, csrftoken)
});

// --- Utilidad para leer cookies del navegador ---
export function getCookie(name) {
  const value = `; ${document.cookie}`;
  const parts = value.split(`; ${name}=`);
  if (parts.length === 2) return parts.pop().split(";").shift();
  return null;
}

// --- Config XSRF de axios para Django ---
api.defaults.xsrfCookieName = "csrftoken";
api.defaults.xsrfHeaderName = "X-CSRFToken";

// --- Interceptor: agrega X-CSRFToken en métodos mutadores ---
api.interceptors.request.use((config) => {
  const method = (config.method || "get").toLowerCase();
  const needsCsrf = ["post", "put", "patch", "delete"].includes(method);

  if (needsCsrf) {
    const token = getCookie("csrftoken");
    if (token) {
      config.headers = config.headers || {};
      config.headers["X-CSRFToken"] = token;
    }
  }

  // NO agregar cabeceras Access-Control-Allow-* desde el cliente.
  return config;
});

// --- Opcional: manejar 401 globalmente ---
api.interceptors.response.use(
  (res) => res,
  (err) => Promise.reject(err)
);

/**
 * Opcional: Llama una vez al iniciar tu app para precargar la cookie 'csrftoken'.
 * Requiere que en Django tengas un endpoint GET con @ensure_csrf_cookie:
 *   path('api/csrf/', csrf_init)
 */
export async function initCsrf() {
  // Asegura que la ruta sea relativa a API_BASE_URL
  // Si tu API base ya termina en /api, aquí quedará /api/csrf/
  const url = "/csrf/";
  try {
    await api.get(url, { withCredentials: true });
  } catch (e) {
    // No romper la app si falla; solo loguear.
    // Puedes mejorar esto con tu logger.
    // console.warn("No se pudo inicializar CSRF:", e);
  }
}

export default api;
